'use client';

import { useEffect, useState } from 'react';

type Page = 'overview' | 'alumni' | 'evaluations' | 'profile' | 'settings' | 'login';

const fallbackAlumni = [
  { name: 'Maya Santos', email: 'maya.santos@email.com', course: 'BS Computer Science', year: '2022', status: 'Employed', initials: 'MS', tone: 'bg-blue-100 text-blue-700' },
  { name: 'Ethan Reyes', email: 'ethan.reyes@email.com', course: 'BS Information Technology', year: '2021', status: 'Employed', initials: 'ER', tone: 'bg-violet-100 text-violet-700' },
  { name: 'Sofia Garcia', email: 'sofia.garcia@email.com', course: 'BS Information Systems', year: '2023', status: 'Seeking', initials: 'SG', tone: 'bg-amber-100 text-amber-700' },
  { name: 'Liam Cruz', email: 'liam.cruz@email.com', course: 'BS Computer Science', year: '2020', status: 'Employed', initials: 'LC', tone: 'bg-emerald-100 text-emerald-700' },
  { name: 'Isabella Flores', email: 'isabella.f@email.com', course: 'BS Information Technology', year: '2022', status: 'Further studies', initials: 'IF', tone: 'bg-rose-100 text-rose-700' },
];

function Icon({ name, size = 19 }: { name: string; size?: number }) {
  const paths: Record<string, React.ReactNode> = {
    grid: <><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></>,
    users: <><path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></>,
    clipboard: <><rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4.5h6a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1ZM9 10h6M9 14h6M9 18h3"/></>,
    chart: <><path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-5 5"/></>,
    settings: <><circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.8 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.8-1l-1.7.7-1.4-2.4L7.1 15a8 8 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.8-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.8 1l1.7-.7 1.4 2.4L19.4 13a8 8 0 0 1 0 2Z"/></>,
    search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,
    bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>,
    arrow: <><path d="M5 12h14M13 6l6 6-6 6"/></>,
    check: <path d="m5 12 4 4L19 6"/>,
    plus: <><path d="M12 5v14M5 12h14"/></>,
    download: <><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5M12 15V3"/></>,
    menu: <><path d="M4 6h16M4 12h16M4 18h16"/></>,
    logout: <><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5M21 12H9"/></>,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] || paths.grid}</svg>;
}

function Brand({ small = false }: { small?: boolean }) {
  return <div className="flex items-center gap-3"><div className={`flex items-center justify-center rounded-xl bg-white/10 text-white ring-1 ring-white/15 ${small ? 'h-9 w-9' : 'h-11 w-11'}`}><span className="text-sm font-bold tracking-tight">C</span></div><div><div className="font-semibold tracking-tight text-white">CICS <span className="font-normal text-blue-200">Connect</span></div><div className="mt-0.5 text-[10px] uppercase tracking-[.17em] text-blue-200/65">Alumni portal</div></div></div>;
}

function DashboardChart({data}:{data:{month:string;count:number}[]}) {
  const max=Math.max(1,...data.map(x=>x.count));
  return <div className="mt-8 flex h-44 items-end gap-2 border-b border-dashed border-slate-200 px-2 pb-1">{data.map((x,i)=><div className="group flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-2" key={`${x.month}-${i}`} title={`${x.month}: ${x.count} responses`}><div className={`w-full rounded-t-md transition-all ${i===data.length-1?'bg-regal-500':'bg-blue-100 group-hover:bg-blue-200'}`} style={{height:`${Math.max(x.count===0?2:8,(x.count/max)*100)}%`}}/><span className="text-[9px] text-slate-400">{x.month}</span></div>)}</div>;
}

type AdminSummary = {
  totalAlumni:number; profileComplete:number; responseCount:number; responseRate:number;
  employedCount:number; unemployedCount:number; employmentRate:number;
  monthlyResponses:{month:string;count:number}[];
  cohorts:{year:number;alumni:number;responses:number}[];
  employment:{status:string|null;count:number}[];
  programs:{name:string|null;count:number}[];
};

function DeanDashboard({summary,error,onReports,onDirectory}:{summary:AdminSummary|null;error:string;onReports:()=>void;onDirectory:()=>void}){
  if(error) return <div className="mt-7 rounded-2xl border border-rose-100 bg-rose-50 p-6 text-sm text-rose-700">{error}</div>;
  if(!summary) return <div className="mt-7 grid gap-4 sm:grid-cols-4">{[...Array(4)].map((_,i)=><div key={i} className="h-28 animate-pulse rounded-2xl bg-slate-100"/>)}</div>;
  return <>
    <div className="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
      <MiniStat title="Total alumni" value={summary.totalAlumni.toLocaleString()} note="Across all graduating years"/>
      <MiniStat title="Employment rate" value={`${summary.employmentRate.toFixed(1)}%`} note={`${summary.employedCount} employed alumni`}/>
      <MiniStat title="Response rate" value={`${summary.responseRate.toFixed(1)}%`} note={`${summary.responseCount} of ${summary.totalAlumni} responses`}/>
      <MiniStat title="Profile complete" value={`${summary.profileComplete}%`} note="Alumni with complete profiles"/>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-2">
      <section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft">
        <div className="flex items-start justify-between gap-3">
          <div><h2 className="text-sm font-semibold text-ink">Monthly responses</h2><p className="mt-1 text-xs text-slate-400">Evaluation submissions over time</p></div>
          <button onClick={onReports} className="text-xs font-semibold text-blue-700 hover:underline">View reports →</button>
        </div>
        <DashboardChart data={summary.monthlyResponses}/>
      </section>
      <section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft">
        <div><h2 className="text-sm font-semibold text-ink">Employment status</h2><p className="mt-1 text-xs text-slate-400">Breakdown from evaluation responses</p></div>
        <div className="mt-6 space-y-4">
          {summary.employment.map(e=>{const total=summary.employment.reduce((a,x)=>a+x.count,0)||1;const pct=Math.round((e.count/total)*100);return <div key={e.status||'unknown'}><div className="mb-1.5 flex justify-between text-xs"><span className="text-slate-600">{e.status||'Not specified'}</span><span className="font-medium text-ink">{pct}%</span></div><div className="h-2 rounded-full bg-slate-100"><div className="h-full rounded-full bg-regal-500" style={{width:`${pct}%`}}/></div></div>;})}
        </div>
      </section>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-2">
      <section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft">
        <div className="flex items-start justify-between gap-3">
          <div><h2 className="text-sm font-semibold text-ink">Cohort breakdown</h2><p className="mt-1 text-xs text-slate-400">Responses by graduating year</p></div>
          <button onClick={onDirectory} className="text-xs font-semibold text-blue-700 hover:underline">View directory →</button>
        </div>
        <div className="mt-5 divide-y divide-slate-50">
          {summary.cohorts.map(c=><div key={c.year} className="flex items-center justify-between py-3 text-xs"><span className="text-slate-600">Class of {c.year}</span><span className="text-slate-500">{c.responses}<span className="text-slate-400"> / {c.alumni} alumni</span></span></div>)}
        </div>
      </section>
      <section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft">
        <div><h2 className="text-sm font-semibold text-ink">Programs</h2><p className="mt-1 text-xs text-slate-400">Alumni by degree program</p></div>
        <div className="mt-5 divide-y divide-slate-50">
          {summary.programs.map(p=><div key={p.name||'unknown'} className="flex items-center justify-between py-3 text-xs"><span className="text-slate-600">{p.name||'Not specified'}</span><span className="font-medium text-ink">{p.count}</span></div>)}
        </div>
      </section>
    </div>
  </>;
}

export default function Home() {
  const [page, setPage] = useState<Page>('login');
  const [role, setRole] = useState<'Dean' | 'Alumni'>('Dean');
  const [loginMode, setLoginMode] = useState<'Alumni' | 'Dean'>('Alumni');
  const [alumniEmail, setAlumniEmail] = useState('');
  const [loginError, setLoginError] = useState('');
  const [mobileOpen, setMobileOpen] = useState(false);
  const [notice, setNotice] = useState('');
  const [query, setQuery] = useState('');
  const [period, setPeriod] = useState('2024–2025');
  const [adminSummary, setAdminSummary] = useState<AdminSummary | null>(null);
  const [adminSummaryError, setAdminSummaryError] = useState('');
  const [alumni, setAlumni] = useState<typeof fallbackAlumni>([]);

  useEffect(() => {
    fetch('/api/dean-session').then(async response => {
      if (response.ok) {
        setRole('Dean');
        setPage('overview');
        return;
      }
      const savedEmail = window.localStorage.getItem('cics-alumni-email');
      if (savedEmail) {
        setAlumniEmail(savedEmail);
        setRole('Alumni');
        setPage('overview');
      }
    }).catch(() => undefined);
  }, []);

  useEffect(() => {
    if (role !== 'Dean' || page === 'login') return;
    let active = true;
    setAdminSummaryError('');
    Promise.all([
      fetch('/api/admin-summary', { cache: 'no-store' }).then(res => res.ok ? res.json() : Promise.reject(new Error('Could not load summary'))),
      fetch('/api/alumni-list', { cache: 'no-store' }).then(res => res.ok ? res.json() : Promise.resolve([]))
    ]).then(([summaryData, listData]) => {
      if (active) {
        setAdminSummary(summaryData as AdminSummary);
        if (Array.isArray(listData)) setAlumni(listData);
      }
    }).catch(error => {
      if (active) setAdminSummaryError(error instanceof Error ? error.message : 'Could not load dashboard data.');
    });
    return () => { active = false; };
  }, [role, page]);

  const changePage = (next: Page) => { setPage(next); setMobileOpen(false); setNotice(''); };
  const nav = role === 'Dean'
    ? [{ id: 'overview' as Page, label: 'Overview', icon: 'grid' }, { id: 'alumni' as Page, label: 'Alumni directory', icon: 'users' }, { id: 'evaluations' as Page, label: 'Evaluations', icon: 'clipboard' }, { id: 'settings' as Page, label: 'Reports & insights', icon: 'chart' }]
    : [{ id: 'overview' as Page, label: 'My overview', icon: 'grid' }, { id: 'profile' as Page, label: 'My profile', icon: 'users' }, { id: 'evaluations' as Page, label: 'Evaluations', icon: 'clipboard' }];

  const title: Record<Page, string> = { overview: role === 'Dean' ? 'Good morning, Dean' : 'Welcome back, Maya', alumni: 'Alumni directory', evaluations: 'Evaluations', profile: 'My profile', settings: 'Reports & insights', login: 'Welcome to CICS Connect' };
  const filtered = alumni.filter(a => `${a.name} ${a.email} ${a.course} ${a.year}`.toLowerCase().includes(query.toLowerCase()));

  if (page === 'login') return <main className="min-h-screen bg-regal-500"><div className="mx-auto grid min-h-screen max-w-6xl items-center gap-10 px-6 py-10 lg:grid-cols-2 lg:px-10"><section className="hidden text-white lg:block"><Brand/><p className="mt-20 max-w-lg text-5xl font-semibold leading-[1.12] tracking-tight">Your CICS story<br/>doesn’t stop at graduation.</p><p className="mt-6 max-w-md text-base leading-7 text-blue-100/75">Stay connected to your department, share your journey, and help shape what comes next.</p><div className="mt-14 flex items-center gap-3 text-sm text-blue-100/70"><span className="flex -space-x-2">{['MS','ER','SG'].map((x,i)=><span key={x} className={`flex h-9 w-9 items-center justify-center rounded-full border-2 border-regal-500 text-[10px] font-bold ${['bg-blue-200 text-blue-900','bg-violet-200 text-violet-900','bg-amber-200 text-amber-900'][i]}`}>{x}</span>)}</span><span>One community, wherever life takes you.</span></div></section><section className="mx-auto w-full max-w-md rounded-3xl bg-white p-8 shadow-2xl shadow-blue-950/20 sm:p-10"><div className="mb-8 lg:hidden"><Brand/></div><p className="text-sm font-semibold text-blue-700">CICS CONNECT</p><h1 className="mt-3 text-3xl font-semibold tracking-tight text-ink">Sign in to continue</h1><p className="mt-2 text-sm leading-6 text-slate-500">Choose your account type to access the CICS alumni community.</p><div className="mt-7 grid grid-cols-2 rounded-xl bg-slate-100 p-1"><button onClick={()=>{setLoginMode('Alumni');setLoginError('');}} className={`rounded-lg py-2.5 text-xs font-semibold ${loginMode==='Alumni'?'bg-white text-regal-500 shadow-sm':'text-slate-500'}`}>Alumni</button><button onClick={()=>{setLoginMode('Dean');setLoginError('');}} className={`rounded-lg py-2.5 text-xs font-semibold ${loginMode==='Dean'?'bg-white text-regal-500 shadow-sm':'text-slate-500'}`}>Dean</button></div>{loginMode==='Alumni'?<><h2 className="mt-7 text-base font-semibold text-ink">Alumni sign in</h2><p className="mt-1 text-xs leading-5 text-slate-500">Enter your email to continue straight to your alumni page.</p><form onSubmit={e=>{e.preventDefault();const d=new FormData(e.currentTarget);const email=String(d.get('email')).trim().toLowerCase();window.localStorage.setItem('cics-alumni-email',email);setAlumniEmail(email);setRole('Alumni');setPage('overview');setNotice('');}} className="mt-5 space-y-4"><label className="block text-xs font-medium text-slate-700">Email address<input name="email" required type="email" placeholder="you@example.com" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none transition focus:border-blue-500 focus:ring-4 focus:ring-blue-100"/></label><button className="flex w-full items-center justify-center gap-2 rounded-xl bg-regal-500 px-4 py-3.5 text-sm font-semibold text-white transition hover:bg-regal-600">Continue to alumni page <Icon name="arrow" size={17}/></button></form><p className="mt-4 text-center text-[11px] leading-5 text-slate-400">Email-only access as requested. This demo does not verify alumni identity.</p></>:<><h2 className="mt-7 text-base font-semibold text-ink">Dean administrator sign in</h2><p className="mt-1 text-xs leading-5 text-slate-500">Use the department administrator account.</p><form onSubmit={async e=>{e.preventDefault();setLoginError('');const d=new FormData(e.currentTarget);try{const res=await fetch('/api/dean-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:d.get('username'),password:d.get('password')})});if(!res.ok)throw new Error('The username or password is incorrect.');window.localStorage.removeItem('cics-alumni-email');setRole('Dean');setPage('overview');setNotice('');}catch(err){setLoginError(err instanceof Error?err.message:'Unable to sign in.');}}} className="mt-5 space-y-4"><label className="block text-xs font-medium text-slate-700">Username<input name="username" required autoComplete="username" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-100"/></label><label className="block text-xs font-medium text-slate-700">Password<input name="password" required type="password" autoComplete="current-password" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-100"/></label><button className="flex w-full items-center justify-center gap-2 rounded-xl bg-regal-500 px-4 py-3.5 text-sm font-semibold text-white transition hover:bg-regal-600">Sign in to dean dashboard <Icon name="arrow" size={17}/></button></form>{loginError&&<p role="alert" className="mt-4 rounded-xl bg-rose-50 p-3 text-xs text-rose-700">{loginError}</p>}<p className="mt-4 text-center text-[11px] leading-5 text-slate-400">Use the Dean account configured in .env.local.</p></>}<div className="my-6 border-t border-slate-100"/><p className="text-center text-xs leading-5 text-slate-400">Access is exclusive to CICS alumni and department administrators.</p></section></div></main>;

  return <div className="min-h-screen bg-canvas">
    <aside className={`fixed inset-y-0 left-0 z-30 flex w-[254px] flex-col bg-regal-500 px-5 pb-5 pt-6 transition-transform duration-200 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
      <Brand/><div className="mt-8 rounded-xl border border-white/10 bg-white/[.07] px-3 py-3"><p className="text-[10px] uppercase tracking-[.15em] text-blue-200/60">Signed in as</p><p className="mt-1 text-xs font-medium text-white">{role==='Dean'?'Department Dean':'CICS Alumni'}</p></div>
      <div className="mt-8 px-3 text-[10px] font-semibold uppercase tracking-[.16em] text-blue-200/55">Workspace</div><nav className="mt-3 space-y-1">{nav.map(item=><button key={item.id} onClick={()=>changePage(item.id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[13px] transition ${page===item.id?'bg-white/14 font-medium text-white':'text-blue-100/70 hover:bg-white/8 hover:text-white'}`}><Icon name={item.icon}/>{item.label}{item.id==='evaluations'&&role==='Dean'&&<span className="ml-auto rounded-full bg-white/15 px-2 py-0.5 text-[10px] text-white">8</span>}</button>)}</nav>
      <div className="mt-auto rounded-2xl border border-white/10 bg-white/[.07] p-4"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-300/20 text-blue-100"><Icon name="clipboard" size={17}/></div><p className="mt-3 text-sm font-medium text-white">Keep your profile current</p><p className="mt-1 text-xs leading-5 text-blue-100/65">Help us celebrate where CICS alumni are today.</p><button onClick={()=>changePage(role==='Dean'?'alumni':'profile')} className="mt-3 text-xs font-semibold text-blue-200 hover:text-white">{role==='Dean'?'View alumni':'Update profile'} <span aria-hidden>→</span></button></div>
      <button onClick={async()=>{window.localStorage.removeItem('cics-alumni-email');await fetch('/api/dean-session',{method:'DELETE'});setRole('Dean');changePage('login');}} className="mt-5 flex items-center gap-3 px-3 py-2 text-xs text-blue-100/65 transition hover:text-white"><Icon name="logout" size={17}/>Sign out</button>
    </aside>
    {mobileOpen&&<button aria-label="Close menu" className="fixed inset-0 z-20 bg-slate-950/30 lg:hidden" onClick={()=>setMobileOpen(false)}/>}
    <div className="min-h-screen lg:pl-[254px]"><header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-slate-200/75 bg-white/90 px-5 backdrop-blur sm:px-8"><div className="flex items-center gap-3"><button className="text-slate-500 lg:hidden" aria-label="Open menu" onClick={()=>setMobileOpen(true)}><Icon name="menu"/></button><div className="hidden text-xs text-slate-400 sm:block">CICS Connect <span className="mx-2 text-slate-300">/</span><span className="text-slate-600">{nav.find(n=>n.id===page)?.label || (page==='settings'?'Reports & insights':'My account')}</span></div><span className="text-sm font-semibold text-ink sm:hidden">{title[page]}</span></div><div className="flex items-center gap-3"><button onClick={()=>setNotice(notice?'':'You’re all caught up — no new notifications.')} aria-label="Notifications" className="relative flex h-9 w-9 items-center justify-center rounded-xl text-slate-500 hover:bg-slate-100"><Icon name="bell"/><i className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-blue-500"/></button><div className="h-7 w-px bg-slate-200"/><button className="flex items-center gap-2.5 rounded-xl py-1 pl-1 pr-2 hover:bg-slate-50"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-100 text-xs font-semibold text-blue-800">{role==='Dean'?'JD':'MS'}</span><span className="hidden text-left sm:block"><span className="block text-xs font-semibold text-ink">{role==='Dean'?'Dean Jordan':'Maya Santos'}</span><span className="mt-0.5 block text-[10px] text-slate-400">{role==='Dean'?'Administrator':'CICS Alumni'}</span></span></button></div></header>
    <main className="mx-auto max-w-[1380px] px-5 py-8 sm:px-8 sm:py-9">
      {notice&&<div className="mb-5 flex items-center justify-between rounded-xl border border-blue-100 bg-blue-50 px-4 py-3 text-sm text-blue-800">{notice}<button onClick={()=>setNotice('')} className="text-blue-700">×</button></div>}
      {page==='overview'&&<>
        <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-slate-500">Tuesday, September 24, 2026</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-ink sm:text-[28px]">{title[page]} <span className="inline-block origin-bottom animate-[wave_1.6s_ease-in-out_infinite]">{role==='Dean'?'👋':'✨'}</span></h1><p className="mt-2 text-sm text-slate-500">{role==='Dean'?'Here’s what’s happening with your alumni community.':'Your CICS community is glad to have you here.'}</p></div><div className="flex items-center gap-2"><select value={period} onChange={e=>setPeriod(e.target.value)} className="rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-xs font-medium text-slate-600 outline-none"><option>2024–2025</option><option>2023–2024</option><option>2022–2023</option></select><button onClick={()=>setNotice('Report prepared. Your dashboard data is ready to export.')} className="flex items-center gap-2 rounded-xl bg-regal-500 px-3.5 py-2.5 text-xs font-semibold text-white shadow-sm hover:bg-regal-600"><Icon name="download" size={15}/> Export report</button></div></div>
        {role==='Dean'?<><DeanDashboard summary={adminSummary} error={adminSummaryError} onReports={()=>changePage('settings')} onDirectory={()=>changePage('alumni')}/></>:<><div className="mt-7 rounded-3xl bg-gradient-to-br from-regal-500 to-blue-700 p-7 text-white sm:p-9"><div className="max-w-lg"><span className="rounded-full border border-white/20 bg-white/10 px-3 py-1 text-[10px] font-medium uppercase tracking-widest text-blue-100">Your alumni community</span><h2 className="mt-5 text-2xl font-semibold leading-tight sm:text-3xl">You’re part of something that keeps growing.</h2><p className="mt-3 max-w-md text-sm leading-6 text-blue-100/80">Update your details and share where your CICS journey has taken you. Your experience helps current students find their way.</p><button onClick={()=>changePage('profile')} className="mt-6 rounded-xl bg-white px-4 py-2.5 text-xs font-semibold text-regal-500 hover:bg-blue-50">Update my profile <span className="ml-1">→</span></button></div></div><div className="mt-5 grid gap-4 sm:grid-cols-3">{[{n:'Class of 2022',l:'Your graduating class',icon:'users'},{n:'Profile 80%',l:'One quick update to finish',icon:'clipboard'},{n:'Your voice matters',l:'Evaluation now open',icon:'chart'}].map(x=><div key={x.n} className="flex items-center gap-4 rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><Icon name={x.icon}/></span><div><p className="text-sm font-semibold text-ink">{x.n}</p><p className="mt-1 text-xs text-slate-400">{x.l}</p></div></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft"><span className="text-xs font-medium text-blue-700">READY WHEN YOU ARE</span><h3 className="mt-3 text-lg font-semibold text-ink">Annual alumni evaluation</h3><p className="mt-2 text-sm leading-6 text-slate-500">Tell us about your work, your career journey, and how CICS prepared you for what came next.</p><button onClick={()=>changePage('evaluations')} className="mt-5 flex items-center gap-2 text-xs font-semibold text-blue-700">Start evaluation <Icon name="arrow" size={15}/></button></div><div className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft"><span className="text-xs font-medium text-slate-400">FROM YOUR DEPARTMENT</span><h3 className="mt-3 text-lg font-semibold text-ink">Help us stay in touch</h3><p className="mt-2 text-sm leading-6 text-slate-500">We’re building a stronger CICS network. Keep your contact details and current role up to date.</p><button onClick={()=>changePage('profile')} className="mt-5 flex items-center gap-2 text-xs font-semibold text-blue-700">Review my profile <Icon name="arrow" size={15}/></button></div></div></>}</>}
      {page==='alumni'&&<><PageHeading title="Alumni directory" subtitle="Explore and connect with your CICS community." action={<button onClick={()=>setNotice('Alumni export is ready to download.')} className="flex items-center gap-2 rounded-xl bg-regal-500 px-4 py-2.5 text-xs font-semibold text-white"><Icon name="download" size={15}/> Export directory</button>}/><div className="mt-7 grid gap-4 sm:grid-cols-3"><MiniStat title="Total alumni" value={adminSummary?.totalAlumni?.toLocaleString() || "1,284"} note="Across all graduating years"/><MiniStat title="Profile complete" value={adminSummary ? `${Math.round((adminSummary.profileComplete / adminSummary.totalAlumni) * 100)}%` : "76%"} note={`${adminSummary?.profileComplete || 976} alumni profiles`}/><MiniStat title="Recently active" value={adminSummary?.responseCount?.toLocaleString() || "214"} note="Submitted an evaluation"/></div><section className="mt-5 rounded-2xl border border-slate-100 bg-white p-5 shadow-soft sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="text-sm font-semibold text-ink">All alumni</h2><p className="mt-1 text-xs text-slate-400">Browse graduate profiles and employment outcomes</p></div><div className="relative"><span className="absolute left-3 top-2.5 text-slate-400"><Icon name="search" size={16}/></span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search alumni…" className="w-full rounded-xl border border-slate-200 py-2.5 pl-9 pr-3 text-xs outline-none focus:border-blue-400 sm:w-64"/></div></div><AlumniTable rows={filtered}/></section></>}
      {page==='evaluations'&&<><PageHeading title="Evaluations" subtitle={role==='Dean'?'Track alumni survey submissions and career outcomes.':'Share your experience to help shape the next generation of CICS graduates.'}/>{role==='Dean'?<><div className="mt-7 grid gap-4 sm:grid-cols-3"><MiniStat title="Responses received" value={adminSummary?.responseCount?.toLocaleString() || "642"} note={`Of ${adminSummary?.totalAlumni?.toLocaleString() || "1,284"} alumni contacted`}/><MiniStat title="Response rate" value={`${adminSummary?.responseRate || 50}%`} note="12.4% increase this year"/><MiniStat title="Awaiting response" value={adminSummary ? (adminSummary.totalAlumni - adminSummary.responseCount).toLocaleString() : "642"} note="Reminder scheduled Oct 1"/></div><section className="mt-5 rounded-2xl border border-slate-100 bg-white p-6 shadow-soft"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-sm font-semibold text-ink">Annual alumni evaluation · 2024–2025</h2><p className="mt-1 text-xs text-slate-400">Survey status by graduating cohort</p></div><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-[10px] font-semibold text-emerald-700">Active</span></div><div className="mt-7 space-y-5">{(adminSummary?.cohorts || [{year:2024, responses:78, alumni:100}]).slice(0, 4).map(x=><div key={x.year}><div className="mb-2 flex justify-between text-xs"><span className="text-slate-600">Class of {x.year}</span><span className="text-slate-500">{x.alumni > 0 ? Math.round((x.responses/x.alumni)*100) : 0}% <span className="text-slate-400">response rate</span></span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-regal-500" style={{width:`${x.alumni > 0 ? (x.responses/x.alumni)*100 : 0}%`}}/></div></div>)}</div><button onClick={()=>setNotice('Evaluation report prepared.')} className="mt-8 rounded-xl border border-slate-200 px-4 py-2.5 text-xs font-semibold text-slate-700 hover:bg-slate-50">Download evaluation report</button></section><section className="mt-5 rounded-2xl border border-slate-100 bg-white p-5 shadow-soft sm:p-6"><h2 className="text-sm font-semibold text-ink">Recent submissions</h2><AlumniTable rows={alumni.slice(0,3)} evaluation/></section></>:<TracerStudyForm email={alumniEmail} onNotice={setNotice}/>}</>}
      {page==='profile'&&<><PageHeading title="My profile" subtitle="Keep your contact details and career information up to date."/><section className="mt-7 max-w-3xl rounded-2xl border border-slate-100 bg-white p-6 shadow-soft sm:p-8"><div className="flex items-center gap-4 border-b border-slate-100 pb-6"><span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-100 text-lg font-semibold text-blue-800">{alumniEmail.slice(0,1).toUpperCase()||'A'}</span><div><h2 className="text-base font-semibold text-ink">Alumni profile</h2><p className="mt-1 text-xs text-slate-400">{alumniEmail}</p></div></div><ProfileForm email={alumniEmail} onSubmit={()=>setNotice('Your profile changes have been saved.')}/></section></>}
      {page==='settings'&&<><PageHeading title="Reports & insights" subtitle="A clearer view of graduate outcomes and department impact." action={<button onClick={()=>setNotice('Annual outcomes report prepared.')} className="flex items-center gap-2 rounded-xl bg-regal-500 px-4 py-2.5 text-xs font-semibold text-white"><Icon name="download" size={15}/> Export report</button>}/><div className="mt-7 grid gap-4 sm:grid-cols-3"><MiniStat title="Employment rate" value={`${adminSummary?.employmentRate || 68.2}%`} note="Based on confirmed responses"/><MiniStat title="Total employed" value={adminSummary?.employedCount?.toLocaleString() || "400"} note="Of employed alumni"/><MiniStat title="Total unemployed" value={adminSummary?.unemployedCount?.toLocaleString() || "14"} note="Currently seeking opportunities"/></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft"><h2 className="text-sm font-semibold text-ink">Employment status</h2><p className="mt-1 text-xs text-slate-400">Respondents from the 2024–2025 evaluation</p><div className="mt-8 space-y-5">{(adminSummary?.employment || [{status:'Employed', count:68}]).map((x, i)=><div key={x.status}><div className="mb-2 flex justify-between text-xs"><span className="text-slate-600">{x.status}</span><span className="font-medium text-ink">{adminSummary?.responseCount ? Math.round((x.count/adminSummary.responseCount)*100) : 0}%</span></div><div className="h-2 rounded-full bg-slate-100"><div className={`h-full rounded-full ${i===0?'bg-regal-500':i===1?'bg-blue-400':i===2?'bg-amber-400':'bg-slate-300'}`} style={{width:`${adminSummary?.responseCount ? (x.count/adminSummary.responseCount)*100 : 0}%`}}/></div></div>)}</div></section><section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-soft"><h2 className="text-sm font-semibold text-ink">Degree programs</h2><p className="mt-1 text-xs text-slate-400">Where our alumni are making an impact</p><div className="mt-5 divide-y divide-slate-100">{(adminSummary?.programs || [{name:'BS Computer Science', count:100}]).slice(0,5).map((p,i)=><div key={p.name} className="flex items-center gap-3 py-3"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-blue-50 text-xs font-semibold text-blue-700">0{i+1}</span><span className="flex-1 text-xs text-slate-600">{p.name}</span><span className="text-xs font-semibold text-ink">{p.count}</span></div>)}</div></section></div></>}
      <footer className="mt-10 flex flex-col justify-between gap-2 border-t border-slate-200/70 py-5 text-[10px] text-slate-400 sm:flex-row"><span>© 2026 CICS Connect · College of Information and Computing Sciences</span><span>Made for our community, wherever you are.</span></footer>
    </main></div>
  </div>;
}

function PageHeading({title,subtitle,action}:{title:string;subtitle:string;action?:React.ReactNode}){return <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-medium uppercase tracking-[.13em] text-blue-700">CICS CONNECT</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-ink sm:text-[28px]">{title}</h1><p className="mt-2 text-sm text-slate-500">{subtitle}</p></div>{action}</div>}
function MiniStat({title,value,note}:{title:string;value:string;note:string}){return <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><p className="text-xs text-slate-500">{title}</p><p className="mt-3 text-2xl font-semibold tracking-tight text-ink">{value}</p><p className="mt-1 text-[11px] text-slate-400">{note}</p></div>}
function AlumniTable({rows,evaluation = false,pageSize = 10,searchable = false,title,subtitle}: {rows: typeof fallbackAlumni;evaluation?: boolean;pageSize?: number;searchable?: boolean;title?: React.ReactNode;subtitle?: React.ReactNode;}) {const [query, setQuery] = useState('');const [page, setPage] = useState(1);const filtered = searchable ? rows.filter(a => `${a.name} ${a.email} ${a.course} ${a.year}`.toLowerCase().includes(query.toLowerCase())): rows;const totalPages = Math.ceil(filtered.length / pageSize) || 1;const paginatedRows = filtered.slice((page - 1) * pageSize, page * pageSize);useEffect(() => { setPage(1); }, [query, rows]);return <section className="mt-5 rounded-2xl border border-slate-100 bg-white p-5 shadow-soft sm:p-6">{(title || searchable) && <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div>{title && <h2 className="text-sm font-semibold text-ink">{title}</h2>}{subtitle && <p className="mt-1 text-xs text-slate-400">{subtitle}</p>}</div>{searchable && <div className="relative"><span className="absolute left-3 top-2.5 text-slate-400"><Icon name="search" size={16}/></span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search alumni…" className="w-full rounded-xl border border-slate-200 py-2.5 pl-9 pr-3 text-xs outline-none focus:border-blue-400 sm:w-64"/></div>}</div>}<div className={title || searchable ? "mt-5 overflow-x-auto" : "overflow-x-auto"}><table className="w-full min-w-[660px] text-left"><thead><tr className="border-y border-slate-100 text-[10px] font-medium uppercase tracking-wider text-slate-400"><th className="py-3 font-medium">Alumni</th><th className="py-3 font-medium">Program</th><th className="py-3 font-medium">Class</th><th className="py-3 font-medium">{evaluation ? 'Evaluation' : 'Employment'}</th><th className="py-3 font-medium">Status</th></tr></thead><tbody>{paginatedRows.map((a, i) =><tr key={a.email} className="border-b border-slate-50 last:border-0"><td className="py-3"><div className="flex items-center gap-3"><span className={`flex h-9 w-9 items-center justify-center rounded-xl text-[10px] font-semibold ${a.tone}`}>{a.initials}</span><span><span className="block text-xs font-semibold text-ink">{a.name}</span><span className="mt-1 block text-[10px] text-slate-400">{a.email}</span></span></div></td><td className="py-3 text-xs text-slate-600">{a.course.replace('BS ', '')}</td><td className="py-3 text-xs text-slate-600">{a.year}</td><td className="py-3 text-xs text-slate-600">{evaluation ? (i === 0 ? 'Submitted' : 'Submitted') : (a.status === 'Employed' ? 'Technology' : '—')}</td><td className="py-3"><span className={`rounded-full px-2.5 py-1 text-[10px] font-medium ${a.status === 'Employed' ? 'bg-emerald-50 text-emerald-700' : a.status === 'Seeking' ? 'bg-amber-50 text-amber-700' : 'bg-blue-50 text-blue-700'}`}>{evaluation ? 'Complete' : a.status}</span></td></tr>)}</tbody></table>{filtered.length === 0 && <p className="py-10 text-center text-sm text-slate-400">No alumni match your search.</p>}</div>{totalPages > 1 && <div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-5 text-xs text-slate-500"><span>Showing {(page - 1) * pageSize + 1} to {Math.min(page * pageSize, filtered.length)} of {filtered.length}</span><div className="flex items-center gap-1"><button disabled={page === 1} onClick={() => setPage(p => p - 1)} className="rounded-lg px-3 py-2 font-medium hover:bg-slate-50 disabled:opacity-50 transition">Previous</button><button disabled={page === totalPages} onClick={() => setPage(p => p + 1)} className="rounded-lg px-3 py-2 font-medium hover:bg-slate-50 disabled:opacity-50 transition">Next</button></div></div>}</section>;}
function ProfileForm({email,onSubmit}:{email:string;onSubmit:()=>void}){const[error,setError]=useState('');const[busy,setBusy]=useState(false);return <form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);const body={email,first_name:f.get('first_name'),last_name:f.get('last_name'),age:f.get('age')?Number(f.get('age')):null,sex:f.get('sex'),current_address:f.get('current_address'),phone_number:f.get('phone_number'),civil_status:f.get('civil_status'),degree_earned:'BSIT',graduation_date:f.get('graduation_date')||null,current_position:f.get('current_position'),current_employer:f.get('current_employer'),contact_consent:f.get('contact_consent')==='on'};try{const response=await fetch('/api/alumni-profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Could not save profile.');onSubmit();}catch(err){setError(err instanceof Error?err.message:'Could not save profile.');}finally{setBusy(false);}}} className="mt-6 grid gap-5 sm:grid-cols-2">{textField('first_name','First name')}{textField('last_name','Last name')}{textField('age','Age','number','',{min:15,max:120})}{selectField('sex','Sex',['Female','Male','Prefer not to say'])}<label className={`${formLabel} sm:col-span-2`}>Current address<input name="current_address" className={fieldClass}/></label>{selectField('civil_status','Civil status',['Single','Married','Widowed','Separated','Prefer not to say'])}{textField('phone_number','Phone number','tel')}<div className="rounded-xl border border-blue-100 bg-blue-50 px-3.5 py-3 text-xs font-medium text-blue-800">Degree earned <span className="float-right font-semibold">BSIT</span></div>{textField('graduation_date','Graduation date','date')}{textField('current_position','Current position')}{textField('current_employer','Current employer')}<label className="flex items-start gap-3 text-xs leading-5 text-slate-500 sm:col-span-2"><input name="contact_consent" type="checkbox" className="mt-1 accent-blue-700"/>The department may contact me about alumni events and CICS updates.</label>{error&&<p role="alert" className="rounded-xl bg-rose-50 p-3 text-xs text-rose-700 sm:col-span-2">{error}</p>}<div className="sm:col-span-2"><button disabled={busy} className="rounded-xl bg-regal-500 px-5 py-3 text-xs font-semibold text-white hover:bg-regal-600 disabled:opacity-60">{busy?'Saving…':'Save changes'}</button></div></form>}
const formLabel = "block text-xs font-medium text-slate-700";
const fieldClass = "mt-2 w-full rounded-xl border border-slate-200 bg-white px-3.5 py-3 text-xs text-slate-700 outline-none focus:border-blue-400 focus:ring-4 focus:ring-blue-50";
const selectField = (name:string, label:string, options:string[], required=false) => <label key={name} className={formLabel}>{label}<select name={name} required={required} defaultValue="" className={fieldClass}><option value="" disabled>Select an option</option>{options.map(o=><option key={o}>{o}</option>)}</select></label>;
const textField = (name:string,label:string,type='text',placeholder='',extra?:{min?:number;max?:number}) => <label key={name} className={formLabel}>{label}<input name={name} type={type} placeholder={placeholder} min={extra?.min} max={extra?.max} className={fieldClass}/></label>;
const choices = (name:string,label:string,options:string[],multiple=false) => <fieldset key={name}><legend className={formLabel}>{label}</legend><div className="mt-2 flex flex-wrap gap-2">{options.map(o=><label key={o} className="cursor-pointer"><input name={name} type={multiple?'checkbox':'radio'} value={o} className="peer sr-only"/><span className="inline-block rounded-xl border border-slate-200 px-3 py-2 text-[11px] text-slate-500 transition peer-checked:border-blue-500 peer-checked:bg-blue-50 peer-checked:text-blue-800">{o}</span></label>)}</div></fieldset>;
const ratingRows = (name:string, items:string[], scale:string[]) => <div className="mt-4 space-y-3">{items.map((item,i)=><fieldset key={item} className="rounded-xl border border-slate-100 p-3"><legend className="px-1 text-xs font-medium leading-5 text-slate-700">{i+1}. {item}</legend><div className="mt-2 flex flex-wrap gap-2">{scale.map((label,j)=><label key={label} className="cursor-pointer"><input type="radio" name={`${name}_${i+1}`} value={j+1} required className="peer sr-only"/><span className="inline-block rounded-lg border border-slate-200 px-2.5 py-1.5 text-[10px] text-slate-500 peer-checked:border-blue-500 peer-checked:bg-blue-50 peer-checked:text-blue-800">{j+1} · {label}</span></label>)}</div></fieldset>)}</div>;
function FormSection({number,title,description,children}:{number:string;title:string;description?:string;children:React.ReactNode}){return <section className="border-b border-slate-100 py-6 last:border-0"><div className="mb-5 flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-blue-50 text-[11px] font-semibold text-blue-700">{number}</span><div><h3 className="text-sm font-semibold text-ink">{title}</h3>{description&&<p className="mt-1 text-xs leading-5 text-slate-400">{description}</p>}</div></div><div className="grid gap-4 sm:grid-cols-2">{children}</div></section>}
function TracerStudyForm({email,onNotice}:{email:string;onNotice:(message:string)=>void}){
  const [busy,setBusy]=useState(false);
  const [toast,setToast]=useState<{type:'success'|'error';message:string}|null>(null);
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{
    e.preventDefault();setToast(null);
    if(!email){setToast({type:'error',message:'Please sign in with your alumni email before submitting.'});return;}
    const form=e.currentTarget;
    setBusy(true);
    const f=new FormData(form);
    const profile={email,degree_earned:'BSIT'};
    const emphasisItems=['Academic, scholarly, and intellectual qualities','Aesthetic, expressive, and creative qualities','Critical, evaluative, and analytical qualities','Information literacy skills','Vocational and occupational competence','Personal relevance and practical value of courses'];
    const skillItems=['Communication skill','Teamwork','Problem solving','Human relations / interpersonal skill','Numeracy / application of numbers','Computer literacy / IT skill','Leadership','Initiative','Adaptability','Skills applicable to a specific job or work','Career-relevant information','Knowledge applicable to a specific job or work'];
    const objectFrom=(prefix:string,items:string[])=>Object.fromEntries(items.map((item,i)=>[item,Number(f.get(`${prefix}_${i+1}`)||0)]));
    const response={academic_year:'2024-2025',course_motivation:f.getAll('motivation'),course_motivation_other:f.get('motivation_other')||null,employment_status:f.get('employment_status')||null,unemployment_reason:f.get('unemployment_reason')||null,employment_location:f.get('employment_location')==='Employed locally'?'Local':f.get('employment_location')==='Employed in a foreign country'?'Foreign':f.get('employment_location')==='Self-employed'?'Self-employed':null,time_to_first_job:f.get('time_to_first_job')||null,delayed_employment_reasons:f.getAll('delay_reason'),delayed_employment_other:f.get('delay_other')||null,applications_before_hire:f.get('applications_before_hire')?Number(f.get('applications_before_hire')):null,tenure_with_current_employer:f.get('employer_tenure')||null,business_sector:f.get('business_sector')||null,business_nature:f.getAll('business_nature'),business_nature_other:f.get('business_other')||null,position_level:f.get('position_level')||null,job_title:f.get('job_title')||null,employment_type:f.get('employment_type')||null,employment_type_other:f.get('employment_other')||null,company_sector:f.get('company_sector')||null,monthly_income_range:f.get('income')||null,employment_alignment:f.get('employment_alignment')||null,development_emphasis:objectFrom('emphasis',emphasisItems),transferable_skills:objectFrom('skill',skillItems),curriculum_recommendations:f.get('recommendations')||null};
    try{
      const result=await fetch('/api/tracer-study',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile,response})});
      const resultBody=await result.json().catch(()=>({}));
      if(!result.ok){setToast({type:'error',message:resultBody.error||'Unable to save the questionnaire. Check your Supabase settings.'});return;}
      setToast({type:'success',message:'Evaluation submitted successfully! Thank you for contributing to the CICS tracer study.'});
      onNotice('Evaluation submitted. Thank you for contributing to the CICS tracer study.');
      form.reset();
    }catch{
      setToast({type:'error',message:'A network error occurred. Please check your connection and try again.'});
    }finally{
      setBusy(false);
    }
  };
  const delayReasons=['No job vacancies','Very few job openings','Strong competition in my field','Lack of professional eligibility requirements','Available jobs outside my field of training','Salary offered is too low','No personal connections or referrals','Lack of work experience','Poor preparation or training','School skills not aligned with industry needs','Did not seek a job immediately','Other'];
  return <>{/* Loading overlay */}
    {busy&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm"><div className="flex flex-col items-center gap-4 rounded-2xl bg-white px-10 py-8 shadow-2xl"><svg className="h-8 w-8 animate-spin text-regal-500" viewBox="0 0 24 24" fill="none"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"/></svg><p className="text-sm font-semibold text-ink">Submitting your evaluation…</p><p className="text-xs text-slate-400">Please wait, do not close this page.</p></div></div>}
    {/* Result modal */}
    {toast&&<div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true"><div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={()=>setToast(null)}/><div className="relative w-full max-w-md rounded-2xl bg-white p-8 shadow-2xl"><div className={`mx-auto flex h-14 w-14 items-center justify-center rounded-full ${toast.type==='success'?'bg-emerald-50':'bg-rose-50'}`}>{toast.type==='success'?<svg className="h-7 w-7 text-emerald-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="m5 12 4 4L19 6"/></svg>:<svg className="h-7 w-7 text-rose-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>}</div><h3 className={`mt-4 text-center text-base font-semibold ${toast.type==='success'?'text-emerald-700':'text-rose-700'}`}>{toast.type==='success'?'Submission successful!':'Submission failed'}</h3><p className="mt-2 text-center text-sm leading-6 text-slate-500">{toast.message}</p><div className="mt-6 flex justify-center"><button onClick={()=>setToast(null)} className={`rounded-xl px-6 py-2.5 text-xs font-semibold text-white ${toast.type==='success'?'bg-emerald-500 hover:bg-emerald-600':'bg-rose-500 hover:bg-rose-600'}`}>{toast.type==='success'?'Done':'Dismiss & retry'}</button></div></div></div>}
    <form onSubmit={submit} className="mt-7 max-w-4xl rounded-2xl border border-slate-100 bg-white px-5 shadow-soft sm:px-8"><div className="border-b border-slate-100 py-6"><span className="rounded-full bg-blue-50 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-blue-700">Graduate tracer study</span><h2 className="mt-4 text-xl font-semibold text-ink">Alumni questionnaire</h2><p className="mt-2 max-w-2xl text-xs leading-5 text-slate-500">Please complete the sections below. Your responses help the department understand graduate outcomes and improve the curriculum. Signed in as <b className="text-slate-700">{email||'alumni account'}</b>.</p></div>
      <div className="mb-5 rounded-xl bg-blue-50 px-4 py-3 text-xs text-blue-800">Profile details are taken from <b>My Profile</b>. Degree earned is recorded as <b>BSIT</b>.</div>
      <FormSection number="01" title="Course motivation" description="Select every reason that motivated you to take your degree."><div className="sm:col-span-2">{choices('motivation','What motivated you to take this course or program?',['To work abroad','Preparation for a higher degree (e.g. medicine, law)','Peer pressure','Parents\u2019 decision','Other'],true)}</div><div className="sm:col-span-2">{textField('motivation_other','Other motivation (if applicable)')}</div></FormSection>
      <FormSection number="02" title="Employment data" description="Tell us about your current work or job search.">{selectField('employment_status','Current employment status',['Employed','Unemployed'],true)}{selectField('unemployment_reason','If unemployed',['Never been employed before','Previously employed'])}{selectField('employment_location','If employed, where?',['Employed locally','Employed in a foreign country','Self-employed'])}{selectField('time_to_first_job','Time from graduation to first job',['Within six months','Within a year','Within a year and a half','Within two years','After two years'])}<div className="sm:col-span-2">{choices('delay_reason','If it took more than a year to find a job, what were the main reasons? (Select all that apply)',delayReasons,true)}</div>{textField('delay_other','Other reason (if applicable)')}{textField('applications_before_hire','Number of applications before landing a job','number')}{textField('employer_tenure','Time with current employer')}
        <div className="sm:col-span-2 rounded-xl bg-slate-50 p-4"><p className="mb-3 text-xs font-semibold text-slate-700">Employer and position</p><div className="grid gap-4 sm:grid-cols-2">{choices('business_nature','Nature of the company business',['Agriculture','Industry','Services'],true)}{textField('business_other','Specify business nature')}{selectField('position_level','Present position level',['Rank and file','Supervisory','Managerial','Proprietor','Consultant','Other'])}{textField('job_title','Job title or position')}{selectField('employment_type','Employment arrangement',['Contractual','Regular / permanent','Temporary / probationary','Other'])}{textField('employment_other','Other employment arrangement')}{selectField('company_sector','Company sector',['Private sector','Government sector'])}{selectField('income','Approximate gross monthly income',['Below \u20b15,000','\u20b15,000\u2013\u20b19,999','\u20b110,000\u2013\u20b114,999','\u20b115,000\u2013\u20b119,999','\u20b120,000\u2013\u20b124,999','\u20b125,000\u2013\u20b129,999','\u20b130,000\u2013\u20b134,999','\u20b135,000 and above'])}{selectField('employment_alignment','How would you rate your employment?',['Underemployed for my degree and competencies','Properly employed for my degree and competencies','Not aligned with my degree'])}</div></div>
      </FormSection>
      <FormSection number="03" title="Program emphasis" description="As a student at L-NU, how strongly was each area emphasized? (1 = Strongly disagree, 5 = Strongly agree)"><div className="sm:col-span-2">{ratingRows('emphasis',['Academic, scholarly, and intellectual qualities','Aesthetic, expressive, and creative qualities','Critical, evaluative, and analytical qualities','Information literacy skills (computers and other information resources)','Vocational and occupational competence','Personal relevance and practical value of courses'],['Strongly disagree','Disagree','Neither','Agree','Strongly agree'])}</div></FormSection>
      <FormSection number="04" title="Transferable skills" description="How much progress did you make in each skill during your college experience? (1 = Very little, 4 = Very much)"><div className="sm:col-span-2">{ratingRows('skill',['Communication skill','Teamwork','Problem solving','Human relations / interpersonal skill','Numeracy / application of numbers','Computer literacy / IT skill','Leadership','Initiative','Adaptability','Skills applicable to a specific job or work','Career-relevant information','Knowledge applicable to a specific job or work'],['Very little','Some','Quite a bit','Very much'])}</div></FormSection>
      <FormSection number="05" title="Curriculum recommendations" description="Share suggestions for improving the curriculum for future graduates."><label className={`${formLabel} sm:col-span-2`}>What should CICS improve or add (subjects, skills, or other preparation)?<textarea name="recommendations" rows={5} className={`${fieldClass} resize-y`} placeholder="Write your recommendations…"/></label></FormSection>
      <div className="pb-7"><p className="mb-4 text-[11px] leading-5 text-slate-400">Your answers will be saved to the CICS alumni database. Complete the Supabase setup and row-level access policies before collecting real alumni data.</p><button disabled={busy} className="flex items-center gap-2 rounded-xl bg-regal-500 px-5 py-3 text-xs font-semibold text-white hover:bg-regal-600 disabled:opacity-60">{busy&&<svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"/></svg>}{busy?'Submitting…':'Submit questionnaire'}</button></div>
    </form>
  </>;
}
